create view public.finance_dashboard with(security_invoker=true) as with bill_totals as(select tenant_id,count(*) filter(where status in('OPEN','PARTIAL','OVERDUE')) outstanding_invoices,coalesce(sum(amount) filter(where status in('OPEN','PARTIAL','OVERDUE')),0) outstanding_amount from public.student_bills group by tenant_id),payment_totals as(select tenant_id,coalesce(sum(amount) filter(where status='CONFIRMED'),0) payment_amount from public.payments group by tenant_id) select b.tenant_id,b.outstanding_invoices,b.outstanding_amount,coalesce(p.payment_amount,0) payment_amount from bill_totals b left join payment_totals p using(tenant_id);revoke all on public.finance_dashboard from anon,authenticated;insert into public.permissions(code,name,description) values('finance_reports.read','Read finance reports','View revenue, receivable, payments, and outstanding') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF') and p.code='finance_reports.read' on conflict do nothing;
